"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";

export default function SignupPage() {
  const router = useRouter();
  const [selectedIcon, setSelectedIcon] = useState<string | null>(null);
  const [error, setError] = useState("");

  const icons = [
    { id: "icon1", label: "🧑‍💻" },
    { id: "icon2", label: "👩‍🎨" },
  ];

  async function handleSubmit(e: React.FormEvent<HTMLFormElement>) {
    e.preventDefault();
    setError("");

    const form = e.target as HTMLFormElement;
    const email = (form.email as HTMLInputElement).value;
    const password = (form.password as HTMLInputElement).value;

    if (!selectedIcon) {
      setError("Kies eerst een avatar!");
      return;
    }

    try {
      const res = await fetch("/api/auth/register", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ email, password, avatar: selectedIcon }),
      });

      const data = await res.json();

      if (!res.ok) {
        setError(data.error || "Er is iets misgegaan!");
        return;
      }

      router.push("/auth/signin");
    } catch (err) {
      console.error("Signup Error:", err);
      setError("Er is iets misgegaan!");
    }
  }

  return (
    <div className="flex flex-col items-center justify-start min-h-screen bg-gray-50 px-4 pt-20">
      <h1 className="text-4xl font-bold mb-6">Registreren</h1>
      <form
        onSubmit={handleSubmit}
        className="w-full max-w-md bg-white p-8 rounded-2xl shadow-xl space-y-6"
      >
        <input
          type="email"
          name="email"
          placeholder="E-mail"
          className="w-full p-3 border rounded-lg"
          required
        />
        <input
          type="password"
          name="password"
          placeholder="Wachtwoord"
          className="w-full p-3 border rounded-lg"
          required
        />

        <div>
          <h2 className="mb-2">Kies je avatar</h2>
          <div className="flex gap-6 mb-2">
            {icons.map((icon) => (
              <button
                key={icon.id}
                type="button"
                onClick={() => setSelectedIcon(icon.id)}
                className={`text-4xl p-4 rounded-xl border-2 transition ${
                  selectedIcon === icon.id
                    ? "border-blue-500 bg-blue-100"
                    : "border-gray-300"
                }`}
              >
                {icon.label}
              </button>
            ))}
          </div>
        </div>

        {error && <p className="text-red-600">{error}</p>}

        <button
          type="submit"
          className="w-full bg-black text-white p-3 rounded-xl font-semibold"
        >
          Registreren
        </button>
      </form>
    </div>
  );
}